// Writes migrations/0002_seed.sql from the design copy in lib/content/*.ts.
//   npx tsx scripts/gen-seed.ts
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';

import { DEFAULT_PRODUCTS } from '../lib/content/products';
import { toRows } from '../lib/content/sections';

const q = (s: string | null) => (s == null ? 'NULL' : `'${s.replace(/'/g, "''")}'`);
const AT = 1794182400000; // 2026-11-09, fixed so the file stays stable between runs

const lines: string[] = [
  '-- Seed: the approved design copy (generated by scripts/gen-seed.ts — do not edit by hand).',
  '',
];

for (const r of toRows()) {
  lines.push(
    `INSERT INTO content (section, key, draft, published, updated_at) VALUES (${q(r.section)}, ${q(r.key)}, NULL, ${q(r.json)}, ${AT});`,
  );
}
lines.push('');
DEFAULT_PRODUCTS.forEach((p, i) => {
  lines.push(
    `INSERT INTO products (id, name, description, category, price, tag, art, image_key, visible, featured, sort) VALUES (${q(p.id)}, ${q(p.name)}, ${q(p.desc)}, ${q(p.category)}, ${p.price ?? 'NULL'}, ${q(p.tag)}, ${q(p.art)}, NULL, 1, ${p.featured ? 1 : 0}, ${(i + 1) * 10});`,
  );
});
lines.push('');
lines.push(`INSERT INTO settings (key, value) VALUES ('ordering_open', 'false');`);
lines.push(`INSERT INTO settings (key, value) VALUES ('last_published', '${AT}');`);
lines.push('');

const out = join(__dirname, '..', 'migrations', '0002_seed.sql');
writeFileSync(out, lines.join('\n'));
console.log('wrote', out);
